import{_ as t,o as a,c as o,aA as i}from"./chunks/framework.CRnIBUQs.js";const h=JSON.parse('{"title":"MRI Simulation and Reconstruction in Julia","description":"","frontmatter":{},"headers":[],"relativePath":"mri-intro.md","filePath":"mri-intro.md","lastUpdated":null}'),r={name:"mri-intro.md"};function n(s,e,l,c,p,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="MRI-Simulation-and-Reconstruction-in-Julia" tabindex="-1">MRI Simulation and Reconstruction in Julia <a class="header-anchor" href="#MRI-Simulation-and-Reconstruction-in-Julia" aria-label="Permalink to &quot;MRI Simulation and Reconstruction in Julia {#MRI-Simulation-and-Reconstruction-in-Julia}&quot;">​</a></h1><p>MRI simulation and reconstruction are core parts of open-source computational imaging research. Before testing methods on scanner-acquired data, researchers often need controlled synthetic data, reproducible reconstructions, and fair cross-method comparisons.</p><p>This MRI track is designed around that research workflow.</p><p>In open-source imaging research, reproducibility is as important as algorithm quality. Researchers need to share acquisition assumptions, reconstruction settings, and output comparisons in a way that other groups can rerun without hidden proprietary dependencies.</p><p>MRI simulation is useful because it provides known ground truth conditions. Reconstruction is useful because it connects those conditions to interpretable images and quantitative metrics. Together, simulation and reconstruction create a practical loop for method development, validation, and transparent comparison.</p><h2 id="Open-Source-Research-Context" tabindex="-1">Open-Source Research Context <a class="header-anchor" href="#Open-Source-Research-Context" aria-label="Permalink to &quot;Open-Source Research Context {#Open-Source-Research-Context}&quot;">​</a></h2><p>In practice, MRI method development usually needs all of the following:</p><ol><li><p>A simulation path to generate reproducible raw data.</p></li><li><p>A reconstruction path for baseline and advanced methods.</p></li><li><p>A comparison path across tools and language ecosystems.</p></li><li><p>Clear documentation so experiments can be repeated by others.</p></li></ol><p>Julia is used here as the orchestration layer for those steps.</p><p>This documentation is written to keep that loop easy to follow from a user perspective: start from high-level context, move through package-specific pages, and then consolidate into an end-to-end implementation page once the code workflow is finalized.</p><h2 id="What-This-Tutorial-Set-Covers" tabindex="-1">What This Tutorial Set Covers <a class="header-anchor" href="#What-This-Tutorial-Set-Covers" aria-label="Permalink to &quot;What This Tutorial Set Covers {#What-This-Tutorial-Set-Covers}&quot;">​</a></h2><p>This tutorial is intentionally split into focused pages. Package-level details are documented in those pages, not here.</p><ul><li><p><a href="./mri-komamri">KomaMRI.jl</a></p></li><li><p><a href="./mri-mrireco">MRIReco.jl</a></p></li><li><p><a href="./mri-bart-bartio">BART and BartIO.jl</a></p></li><li><p><a href="./mri-interop">Interoperability (PythonCall/C++)</a></p></li><li><p><a href="./mri-workflow">End-to-End Workflow</a></p></li></ul>',13)])])}const m=t(r,[["render",n]]);export{h as __pageData,m as default};
